interface နိုင်တွက် { int တန်ဖိုး(); }
class နောက်ခံတန်ဖိုး { static int ပြင်ဆင် = 7; int ကိန်းတန်ဖိုး; String အမည်; နောက်ခံတန်ဖိုး(int ကိန်းတန်ဖိုး) { this.ကိန်းတန်ဖိုး = ကိန်းတန်ဖိုး; အမည် = "နောက်ခံတန်ဖိုး"; } int တန်ဖိုး() { return ကိန်းတန်ဖိုး; } }
class အခွဲတန်ဖိုး extends နောက်ခံတန်ဖိုး implements နိုင်တွက် { အခွဲတန်ဖိုး(int ကိန်းတန်ဖိုး) { super(ကိန်းတန်ဖိုး); အမည် = "အခွဲတန်ဖိုး"; } public int တန်ဖိုး() { return ကိန်းတန်ဖိုး * ပြင်ဆင်; } }
public class အရာဝတ္ထုစမ်းသပ် {
    static int အစဦးအခြေအနေ = နောက်ခံတန်ဖိုး.ပြင်ဆင် + 2;
    static int အခွဲ(int ကိန်းတန်ဖိုး) { switch (ကိန်းတန်ဖိုး) { case 1: return 12; case 2: return 23; case 3: return 34; default: return -1; } }
    static int ကျဲတန်ဖိုး(int ကိန်းတန်ဖိုး) { switch (ကိန်းတန်ဖိုး) { case -1: return 91; case 100: return 92; default: return 90; } }
    public static void main(String[] အချက်များ) {
        အခွဲတန်ဖိုး ဒုတိယတွက်ချက်ခံ = new အခွဲတန်ဖိုး(6); နောက်ခံတန်ဖိုး တတိယအော်ပရန်း = ဒုတိယတွက်ချက်ခံ; နိုင်တွက် စတုတ္ထအော်ပရန်း = ဒုတိယတွက်ချက်ခံ;
        System.out.println(အစဦးအခြေအနေ + ":" + ဒုတိယတွက်ချက်ခံ.အမည် + ":" + တတိယအော်ပရန်း.တန်ဖိုး() + ":" + စတုတ္ထအော်ပရန်း.တန်ဖိုး());
        System.out.println((တတိယအော်ပရန်း instanceof အခွဲတန်ဖိုး) + ":" + (တတိယအော်ပရန်း instanceof နိုင်တွက်) + ":" + အခွဲ(2) + ":" + ကျဲတန်ဖိုး(100));
        Object[] အခင်းအကျင်းတန်ဖိုး = new Object[3]; အခင်းအကျင်းတန်ဖိုး[0] = ဒုတိယတွက်ချက်ခံ; အခင်းအကျင်းတန်ဖိုး[1] = "한글😀"; System.gc();
        System.out.println(((အခွဲတန်ဖိုး)အခင်းအကျင်းတန်ဖိုး[0]).တန်ဖိုး()); System.out.println((String)အခင်းအကျင်းတန်ဖိုး[1]);
        int[] အရေအတွက်စာရင်း = {1, 2, 3, 4}; System.arraycopy(အရေအတွက်စာရင်း, 0, အရေအတွက်စာရင်း, 1, 3); System.out.println(အရေအတွက်စာရင်း[3]);
        byte[] ဘိုက်တန်ဖိုး = new byte[1]; ဘိုက်တန်ဖိုး[0] = (byte)255; char[] အက္ခရာ = {'한'}; short[] ဖြစ်သောတို = {(short)65535}; boolean[] ယုတ္တိတန်ဖိုးတန်ဖိုး = {true};
        System.out.println(ဘိုက်တန်ဖိုး[0] + ":" + အက္ခရာ[0] + ":" + ဖြစ်သောတို[0] + ":" + ယုတ္တိတန်ဖိုးတန်ဖိုး[0]);
    }
}
